def min_separated_cities(n, m, roads):
    # Create adjacency list for the graph
    graph = {i: [] for i in range(1, n + 1)}
    for x, y in roads:
        graph[x].append(y)

    # Find all nodes with no incoming edges
    incoming_edges = {i: 0 for i in range(1, n + 1)}
    for neighbors in graph.values():
        for neighbor in neighbors:
            incoming_edges[neighbor] += 1

    # Count nodes with no incoming edges
    separate_cities = sum(1 for count in incoming_edges.values() if count == 0)

    # The minimum number of separate cities is the maximum of 1 or the number of separate cities
    return max(1, separate_cities)

